// Checks and reads through one descriptor, so the file that was checked is the
// file that is read.
export function readLedger(path) {
  const fd = openSync(path, 'r');
  try {
    if (!fstatSync(fd).isFile()) throw new Error(`${path} is not a file`);
    return parseLedger(readFileSync(fd, 'utf8'));
  } finally {
    closeSync(fd);
  }
}

input.new_string:
// A read-only descriptor for path that closes itself when its `using` block
// ends, whether by return or by throw.
function openForReading(path) {
  const fd = openSync(path, 'r');
  return {
    fd,
    [Symbol.dispose]() {
      closeSync(fd);
    },
  };
}

// Checks and reads through one descriptor, so the file that was checked is the
// file that is read.
export function readLedger(path) {
  using file = openForReading(path);
  if (!fstatSync(file.fd).isFile()) throw new Error(`${path} is not a file`);
  return parseLedger(readFileSync(file.fd, 'utf8'));
}

