2	export async function mapLimit(items, limit, fn) {
3	  const results = new Array(items.length);
4	  let next = 0;
5	
6	  async function lane() {
7	    while (next < items.length) {
8	      const index = next++;
9	      results[index] = await fn(items[index], index);
10	    }
11	  }
12	
13	  const lanes = Math.max(1, Math.min(limit, items.length));
14	  await Promise.all(Array.from({ length: lanes }, lane));
15	  return results;
